import sys, os, re, json, math
from datetime import datetime, timezone
from fractions import Fraction

QS = ['temp', 'rh', 'pres', 'wspd', 'wdir', 'rain']
RANGE = {'temp': (-50, 60), 'rh': (0, 100), 'pres': (870, 1085),
         'wspd': (0, 60), 'wdir': (0, 360), 'rain': (0, 5000)}
CONV = {
    ('temp', 'degC'): lambda v: v,
    ('temp', 'degF'): lambda v: (v - 32) * 5 / 9,
    ('temp', 'K'): lambda v: v - 273.15,
    ('rh', 'pct'): lambda v: v,
    ('rh', 'frac'): lambda v: v * 100,
    ('pres', 'hPa'): lambda v: v,
    ('pres', 'kPa'): lambda v: v * 10,
    ('pres', 'inHg'): lambda v: v * 33.8638866667,
    ('pres', 'mmHg'): lambda v: v * 1.33322387415,
    ('wspd', 'ms'): lambda v: v,
    ('wspd', 'kmh'): lambda v: v / 3.6,
    ('wspd', 'kn'): lambda v: v * 1852 / 3600,
    ('wspd', 'mph'): lambda v: v * 0.44704,
    ('wdir', 'deg'): lambda v: v,
    ('rain', 'mm'): lambda v: v,
}
DIRRE = re.compile(r'^#\s*([a-z]+):(.*)$')


def conv_for(q, unit):
    if q == 'rain' and unit.startswith('tips:'):
        s = float(unit[5:])
        return lambda v: v * s
    return CONV.get((q, unit), lambda v: v)


def is_missing(s):
    if s == '' or s == '---' or s.lower() == 'nan':
        return True
    return re.fullmatch(r'-9999(\.0*)?', s) is not None


def parse_time(s):
    s = s.strip().replace('T', ' ')
    d = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    return int(d.replace(tzinfo=timezone.utc).timestamp())


def parse_tz(s):
    s = s.strip()
    if s == 'Z':
        return 0
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return sign * (int(h) * 3600 + int(m) * 60)


def parse_file(path):
    with open(path, 'rb') as f:
        text = f.read().decode('utf-8-sig')
    meta = {}
    cols = None
    units = {}
    rows = []
    syncs = []
    for line in text.splitlines():
        if not line.strip():
            continue
        if line[0] == '#':
            m = DIRRE.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k in ('station', 'upload', 'interval', 'tz'):
                meta[k] = v
            elif k == 'columns':
                cols = [c.strip() for c in v.split(',')]
            elif k == 'units':
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        units[a] = b
            elif k == 'sync':
                d = {}
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        d[a] = b
                if 'logger' in d and 'ref' in d:
                    syncs.append((d['logger'], d['ref']))
            continue
        if cols is None:
            continue
        fields = [x.strip() for x in line.split(',')]
        rec = {'t': parse_time(fields[cols.index('time')]), 'v': {}}
        for c, x in zip(cols, fields):
            if c == 'time' or c not in RANGE or is_missing(x):
                continue
            try:
                val = conv_for(c, units.get(c, ''))(float(x))
            except ValueError:
                continue
            lo, hi = RANGE[c]
            if lo <= val <= hi:
                rec['v'][c] = val
        rows.append(rec)
    return meta, rows, syncs


def main(indir, outfile):
    files = sorted(n for n in os.listdir(indir)
                   if n.endswith('.log') and os.path.isfile(os.path.join(indir, n)))
    st = {}
    for n in files:
        meta, rows, syncs = parse_file(os.path.join(indir, n))
        if 'station' not in meta:
            continue
        tz = parse_tz(meta.get('tz', 'Z'))
        up = int(meta.get('upload', 0))
        s = st.setdefault(meta['station'], {'interval': None, 'rows': {}, 'sync': {}})
        if 'interval' in meta:
            s['interval'] = int(float(meta['interval']))
        for r in rows:
            u = r['t'] - tz
            old = s['rows'].get(u)
            if old is None or up > old[0]:
                s['rows'][u] = (up, r['v'])
        for lg, ref in syncs:
            u = parse_time(lg) - tz
            rf = int(datetime.strptime(ref, '%Y-%m-%dT%H:%M:%SZ')
                     .replace(tzinfo=timezone.utc).timestamp())
            old = s['sync'].get(u)
            if old is None or up > old[0]:
                s['sync'][u] = (up, rf - u)
    out = []
    for sid in sorted(st):
        s = st[sid]
        if not s['rows']:
            continue
        iv = s['interval']
        sp = sorted((t, o[1]) for t, o in s['sync'].items())
        import bisect
        ts = [t for t, _ in sp]

        def offset(t):
            if not sp:
                return 0
            if t <= ts[0]:
                return sp[0][1]
            if t >= ts[-1]:
                return sp[-1][1]
            i = bisect.bisect_left(ts, t)
            if ts[i] == t:
                return sp[i][1]
            t1, o1 = sp[i - 1]
            t2, o2 = sp[i]
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)
        recs = []
        for u, (_, v) in s['rows'].items():
            recs.append((u + offset(u), v))
        recs.sort(key=lambda x: x[0])
        hour = lambda c: -((-c) // 3600) * 3600
        h0, h1 = hour(recs[0][0]), hour(recs[-1][0])
        data = {h: {q: {'vals': [], 'vec': [0.0, 0.0], 'nv': 0, 'rain': 0.0, 'n': 0} for q in QS}
                for h in range(h0, h1 + 1, 3600)}
        prev = None
        for c, v in recs:
            h = hour(c)
            d = data[h]
            for q, x in v.items():
                d[q]['n'] += 1
                if q in ('temp', 'rh', 'pres', 'wspd'):
                    d[q]['vals'].append(x)
                elif q == 'wdir':
                    if v.get('wspd', 0) > 0:
                        a = math.radians(x)
                        d[q]['vec'][0] += math.sin(a)
                        d[q]['vec'][1] += math.cos(a)
                        d[q]['nv'] += 1
                elif q == 'rain':
                    if prev is not None and (c - prev[0]) * 2 <= 5 * iv:
                        d[q]['rain'] += x - prev[1] if x >= prev[1] else x
                    prev = (c, x)
        hours = []
        for h in range(h0, h1 + 1, 3600):
            e = {'hour': datetime.fromtimestamp(h, timezone.utc).strftime('%Y-%m-%dT%H:00:00Z')}
            expected = 3600 // iv
            for q in QS:
                d = data[h][q]
                n = d['n']
                val = None
                if n * 4 >= expected * 3:
                    if q == 'rain':
                        val = round(d['rain'], 2)
                    elif q == 'wdir':
                        if d['nv']:
                            a = math.degrees(math.atan2(d['vec'][0], d['vec'][1])) % 360
                            val = round(a, 2)
                            if val >= 360:
                                val = 0.0
                    elif d['vals']:
                        val = round(math.fsum(d['vals']) / len(d['vals']), 2)
                e[q] = {'value': val, 'n': n}
            hours.append(e)
        out.append({'station': sid, 'interval_s': iv, 'hours': hours})
    with open(outfile, 'w') as f:
        json.dump({'stations': out}, f)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
